/**
 * BR-AUTH-01..11：授权用例编排（Mockito 隔离下游与仓储）。
 */
@ExtendWith(MockitoExtension.class)
class AuthorizationServiceTest {

    private static final String CARD_NUMBER = "0500024453765740";
    private static final String ACCOUNT_ID = "00000000001";
    private static final String CUSTOMER_ID = "000000001";

    @Mock
    private AuthorizationRepository authorizations;

    @Mock
    private AuthorizationSummaryRepository summaries;

    @Mock
    private CardFraudFlagRepository fraudFlags;

    @Mock
    private CardClient cardClient;

    @Mock
    private AccountClient accountClient;

    @Mock
    private CustomerClient customerClient;

    private AuthorizationService service;

    private final CardSnapshot card = new CardSnapshot(CARD_NUMBER, ACCOUNT_ID, CUSTOMER_ID, "Y",
            LocalDate.of(2028, 5, 20));

    private final CustomerSnapshot customer = new CustomerSnapshot(CUSTOMER_ID);

    private final AccountSnapshot account = new AccountSnapshot(ACCOUNT_ID, "Y",
            new BigDecimal("1940.00"), new BigDecimal("2020.00"), new BigDecimal("1020.00"));

    @BeforeEach
    void setUp() {
        service = new AuthorizationService(authorizations, summaries, fraudFlags, cardClient,
                accountClient, customerClient, new AuthorizationPolicy());
    }

    private AuthorizationCommand command(String amount) {
        return new AuthorizationCommand(CARD_NUMBER, new BigDecimal(amount), "01", "2805", "0100", "POS",
                "000000", "5411", "USA", 5, "MERCHANT0000001", "Corner Grocery", "Springfield", "IL",
                "62704", "TXN000000000001", LocalDateTime.of(2026, 10, 25, 10, 15));
    }

    private void stubExistingCardAndParties() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(customerClient.findCustomer(CUSTOMER_ID)).thenReturn(Optional.of(customer));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account));
    }

    @Test
    void approvesAndAccumulatesSummaryFromAccountLimits() {
        stubExistingCardAndParties();
        when(summaries.findSummary(ACCOUNT_ID)).thenReturn(Optional.empty());
        when(fraudFlags.findFlag(CARD_NUMBER)).thenReturn(Optional.empty());

        AuthorizationResult result = service.authorize(command("50.00"));

        assertThat(result.authorizationId()).isNotBlank();
        assertThat(result.responseCode()).isEqualTo("00");
        assertThat(result.reasonCode()).isEqualTo("0000");
        assertThat(result.approvedAmount()).isEqualByComparingTo("50.00");
        assertThat(result.accountId()).isEqualTo(ACCOUNT_ID);
        assertThat(result.customerId()).isEqualTo(CUSTOMER_ID);
        assertThat(result.fraudFlag()).isEqualTo("N");
        assertThat(result.authTimestamp()).isEqualTo(LocalDateTime.of(2026, 10, 25, 10, 15));

        ArgumentCaptor<AuthorizationCase> detailCaptor = ArgumentCaptor.forClass(AuthorizationCase.class);
        verify(authorizations).saveAuthorization(detailCaptor.capture());
        AuthorizationCase detail = detailCaptor.getValue();
        assertThat(detail.getResponseCode()).isEqualTo("00");
        assertThat(detail.getTransactionAmount()).isEqualByComparingTo("50.00");
        assertThat(detail.getCreatedAt()).isNotNull();

        ArgumentCaptor<AuthorizationSummary> summaryCaptor = ArgumentCaptor.forClass(AuthorizationSummary.class);
        verify(summaries).saveSummary(summaryCaptor.capture());
        AuthorizationSummary saved = summaryCaptor.getValue();
        assertThat(saved.getCreditLimit()).isEqualByComparingTo("2020.00");
        assertThat(saved.getCashLimit()).isEqualByComparingTo("1020.00");
        assertThat(saved.getApprovedCount()).isEqualTo(1);
        assertThat(saved.getApprovedAmount()).isEqualByComparingTo("50.00");
        assertThat(saved.getCreditBalance()).isEqualByComparingTo("50.00");
        assertThat(saved.getDeclinedCount()).isZero();
        assertThat(saved.getDeclinedAmount()).isEqualByComparingTo("0.00");
    }

    @Test
    void declinesInsufficientFundsAndCountsDeclinedAmount() {
        stubExistingCardAndParties();
        when(summaries.findSummary(ACCOUNT_ID)).thenReturn(Optional.empty());
        when(fraudFlags.findFlag(CARD_NUMBER)).thenReturn(Optional.empty());

        AuthorizationResult result = service.authorize(command("500.00"));

        assertThat(result.responseCode()).isEqualTo("05");
        assertThat(result.reasonCode()).isEqualTo("4100");
        assertThat(result.approvedAmount()).isEqualByComparingTo("0.00");

        ArgumentCaptor<AuthorizationSummary> summaryCaptor = ArgumentCaptor.forClass(AuthorizationSummary.class);
        verify(summaries).saveSummary(summaryCaptor.capture());
        AuthorizationSummary saved = summaryCaptor.getValue();
        assertThat(saved.getDeclinedCount()).isEqualTo(1);
        assertThat(saved.getDeclinedAmount()).isEqualByComparingTo("500.00");
        assertThat(saved.getApprovedCount()).isZero();
        assertThat(saved.getCreditBalance()).isEqualByComparingTo("0.00");
    }

    @Test
    void updatesExistingSummaryInPlace() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(customerClient.findCustomer(CUSTOMER_ID)).thenReturn(Optional.of(customer));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(new AccountSnapshot(
                ACCOUNT_ID, "Y", new BigDecimal("0.00"), new BigDecimal("2020.00"),
                new BigDecimal("1020.00"))));
        AuthorizationSummary existing = new AuthorizationSummary(ACCOUNT_ID, new BigDecimal("2020.00"),
                new BigDecimal("1020.00"));
        existing.applyApproved(new BigDecimal("1000.00"));
        when(summaries.findSummary(ACCOUNT_ID)).thenReturn(Optional.of(existing));
        when(fraudFlags.findFlag(CARD_NUMBER)).thenReturn(Optional.empty());

        AuthorizationResult result = service.authorize(command("120.00"));

        assertThat(result.responseCode()).isEqualTo("00");
        assertThat(existing.getApprovedCount()).isEqualTo(2);
        assertThat(existing.getApprovedAmount()).isEqualByComparingTo("1120.00");
        assertThat(existing.getCreditBalance()).isEqualByComparingTo("1120.00");
        verify(summaries).saveSummary(existing);
    }

    @Test
    void doesNotPersistWhenCardDoesNotExist() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.empty());

        AuthorizationResult result = service.authorize(command("100.00"));

        assertThat(result.responseCode()).isEqualTo("05");
        assertThat(result.reasonCode()).isEqualTo("3100");
        assertThat(result.approvedAmount()).isEqualByComparingTo("0.00");
        assertThat(result.accountId()).isNull();
        assertThat(result.customerId()).isNull();
        verifyNoInteractions(authorizations);
        verifyNoInteractions(summaries);
    }

    @Test
    void persistsDetailButSkipsSummaryWhenAccountDoesNotExist() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(customerClient.findCustomer(CUSTOMER_ID)).thenReturn(Optional.of(customer));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.empty());

        AuthorizationResult result = service.authorize(command("100.00"));

        assertThat(result.responseCode()).isEqualTo("05");
        assertThat(result.reasonCode()).isEqualTo("3100");
        assertThat(result.accountId()).isEqualTo(ACCOUNT_ID);
        assertThat(result.customerId()).isEqualTo(CUSTOMER_ID);

        ArgumentCaptor<AuthorizationCase> detailCaptor = ArgumentCaptor.forClass(AuthorizationCase.class);
        verify(authorizations).saveAuthorization(detailCaptor.capture());
        assertThat(detailCaptor.getValue().getResponseCode()).isEqualTo("05");
        assertThat(detailCaptor.getValue().getAccountId()).isEqualTo(ACCOUNT_ID);
        verify(summaries, never()).saveSummary(any());
    }

    @Test
    void marksFraudOnDetailAndCardFlagIdempotently() {
        AuthorizationCase existing = new AuthorizationCase(new AuthorizationRequest(CARD_NUMBER,
                LocalDateTime.of(2026, 10, 25, 10, 15), new BigDecimal("120.00"), "01", "2805", "0100",
                "POS", "000000", "5411", "USA", 5, "MERCHANT0000001", "Corner Grocery", "Springfield",
                "IL", "62704", "TXN000000000001", ACCOUNT_ID, CUSTOMER_ID));
        existing.decide("00", "0000", new BigDecimal("120.00"));
        when(authorizations.findAuthorization(existing.getAuthorizationId())).thenReturn(Optional.of(existing));

        AtomicReference<CardFraudFlag> stored = new AtomicReference<>();
        when(fraudFlags.findFlag(CARD_NUMBER)).thenAnswer(invocation -> Optional.ofNullable(stored.get()));
        when(fraudFlags.saveFlag(any())).thenAnswer(invocation -> {
            CardFraudFlag flag = invocation.getArgument(0);
            stored.set(flag);
            return flag;
        });

        FraudResult first = service.markFraud(existing.getAuthorizationId());
        FraudResult second = service.markFraud(existing.getAuthorizationId());

        assertThat(first.fraudFlag()).isEqualTo("Y");
        assertThat(first.cardNumber()).isEqualTo(CARD_NUMBER);
        assertThat(first.cardBlocked()).isTrue();
        assertThat(second).isEqualTo(first);
        assertThat(existing.getFraudFlag()).isEqualTo("Y");
        assertThat(stored.get().getAuthorizationId()).isEqualTo(existing.getAuthorizationId());
        assertThat(stored.get().getReason())
                .isEqualTo("Marked fraud from authorization " + existing.getAuthorizationId());
        verify(fraudFlags, times(2)).saveFlag(any());
    }
}

package com.carddemo.authorization.domain.service;

import com.carddemo.authorization.domain.exception.BusinessRuleException;
import com.carddemo.authorization.domain.model.AccountSnapshot;
import com.carddemo.authorization.domain.model.AuthorizationSummary;
import com.carddemo.authorization.domain.model.CardSnapshot;
import com.carddemo.authorization.domain.model.CustomerSnapshot;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * BR-AUTH-01..09：决策与原因码优先级（纯 JUnit，无 Spring）。
 */
class AuthorizationPolicyTest {

    private static final BigDecimal CREDIT_LIMIT = new BigDecimal("2020.00");
    private static final BigDecimal CURRENT_BALANCE = new BigDecimal("1940.00");

    private final AuthorizationPolicy policy = new AuthorizationPolicy();

    private final CardSnapshot card = new CardSnapshot("0500024453765740", "00000000001", "000000001",
            "Y", LocalDate.of(2028, 5, 20));

    private final CustomerSnapshot customer = new CustomerSnapshot("000000001");

    private final AccountSnapshot account = new AccountSnapshot("00000000001", "Y",
            CURRENT_BALANCE, CREDIT_LIMIT, new BigDecimal("1020.00"));

    @Test
    void approvesAmountWithinAvailableCredit() {
        AuthorizationPolicy.Decision decision = policy.decide(card, customer, account, null, false,
                new BigDecimal("80.00"));

        assertThat(decision.responseCode()).isEqualTo("00");
        assertThat(decision.reasonCode()).isEqualTo("0000");
        assertThat(decision.approvedAmount()).isEqualByComparingTo("80.00");
    }

    @Test
    void declinesWith3100WhenCardDoesNotExist() {
        AuthorizationPolicy.Decision decision = policy.decide(null, customer, account, null, false,
                new BigDecimal("10.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("3100");
        assertThat(decision.approvedAmount()).isEqualByComparingTo("0.00");
    }

    @Test
    void declinesWith3100WhenCustomerDoesNotExist() {
        AuthorizationPolicy.Decision decision = policy.decide(card, null, account, null, false,
                new BigDecimal("10.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("3100");
    }

    @Test
    void declinesWith3100WhenAccountDoesNotExist() {
        AuthorizationPolicy.Decision decision = policy.decide(card, customer, null, null, false,
                new BigDecimal("10.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("3100");
    }

    @Test
    void declinesWith4100WhenAmountExceedsAvailableCredit() {
        AuthorizationPolicy.Decision decision = policy.decide(card, customer, account, null, false,
                new BigDecimal("80.01"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("4100");
        assertThat(decision.approvedAmount()).isEqualByComparingTo("0.00");
    }

    @Test
    void declinesWith4100WhenPendingSummaryConsumesCredit() {
        AuthorizationSummary summary = new AuthorizationSummary("00000000001", CREDIT_LIMIT,
                new BigDecimal("1020.00"));
        summary.applyApproved(new BigDecimal("2000.00"));

        AuthorizationPolicy.Decision decision = policy.decide(card, customer, account, summary, false,
                new BigDecimal("30.00"));

        assertThat(decision.reasonCode()).isEqualTo("4100");
    }

    @Test
    void subtractsAccountBalanceAndPendingApprovalsTogether() {
        AuthorizationSummary summary = new AuthorizationSummary("00000000001", CREDIT_LIMIT,
                new BigDecimal("1020.00"));
        summary.applyApproved(new BigDecimal("50.00"));

        AuthorizationPolicy.Decision decision = policy.decide(card, customer, account, summary, false,
                new BigDecimal("50.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("4100");
    }

    @Test
    void declinesWith4200WhenCardIsNotActive() {
        CardSnapshot inactive = new CardSnapshot(card.cardNumber(), card.accountId(), card.customerId(),
                "N", card.expiryDate());

        AuthorizationPolicy.Decision decision = policy.decide(inactive, customer, account, null, false,
                new BigDecimal("80.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("4200");
    }

    @Test
    void declinesWith4300WhenAccountIsClosed() {
        AccountSnapshot closed = new AccountSnapshot("00000000001", "N", CURRENT_BALANCE, CREDIT_LIMIT,
                new BigDecimal("1020.00"));

        AuthorizationPolicy.Decision decision = policy.decide(card, customer, closed, null, false,
                new BigDecimal("80.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("4300");
    }

    @Test
    void declinesWith5100WhenCardIsFraudFlagged() {
        AuthorizationPolicy.Decision decision = policy.decide(card, customer, account, null, true,
                new BigDecimal("80.00"));

        assertThat(decision.responseCode()).isEqualTo("05");
        assertThat(decision.reasonCode()).isEqualTo("5100");
    }

    /**
     * BR-AUTH-09：额度不足（4100）优先于卡未激活（4200）。
     */
    @Test
    void prioritisesInsufficientFundOverInactiveCard() {
        CardSnapshot inactive = new CardSnapshot(card.cardNumber(), card.accountId(), card.customerId(),
                "N", card.expiryDate());

        AuthorizationPolicy.Decision decision = policy.decide(inactive, customer, account, null, false,
                new BigDecimal("500.00"));

        assertThat(decision.reasonCode()).isEqualTo("4100");
    }

    @Test
    void rejectsNonPositiveTransactionAmount() {
        assertThatThrownBy(() -> policy.decide(card, customer, account, null, false, new BigDecimal("0.00")))
                .isInstanceOf(BusinessRuleException.class)
                .hasMessageContaining("greater than zero");
    }
}

package com.carddemo.authorization.interfaces.rest;

import com.carddemo.authorization.domain.model.AccountSnapshot;
import com.carddemo.authorization.domain.model.AuthorizationCase;
import com.carddemo.authorization.domain.model.AuthorizationRequest;
import com.carddemo.authorization.domain.model.AuthorizationSummary;
import com.carddemo.authorization.domain.model.CardSnapshot;
import com.carddemo.authorization.domain.model.CustomerSnapshot;
import com.carddemo.authorization.domain.repository.AuthorizationRepository;
import com.carddemo.authorization.domain.repository.AuthorizationSummaryRepository;
import com.carddemo.authorization.infrastructure.client.AccountClient;
import com.carddemo.authorization.infrastructure.client.CardClient;
import com.carddemo.authorization.infrastructure.client.CustomerClient;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 端到端用例：H2 + Flyway + MockMvc；card-service / account-service / customer-service 用 @MockBean 替换。
 * 可用额度：账户额度 2020.00 − 当前余额 1940.00 = 80.00；出现汇总后改为 信用额度 − 信用余额。
 */
@SpringBootTest
@AutoConfigureMockMvc
@ActiveProfiles("test")
@Transactional
class AuthorizationControllerTest {

    private static final String CARD_NUMBER = "0500024453765740";
    private static final String ACCOUNT_ID = "00000000001";
    private static final String CUSTOMER_ID = "000000001";

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private AuthorizationRepository authorizations;

    @Autowired
    private AuthorizationSummaryRepository summaries;

    @MockBean
    private CardClient cardClient;

    @MockBean
    private AccountClient accountClient;

    @MockBean
    private CustomerClient customerClient;

    private final CardSnapshot card = new CardSnapshot(CARD_NUMBER, ACCOUNT_ID, CUSTOMER_ID, "Y",
            LocalDate.of(2028, 5, 20));

    private final AccountSnapshot account = new AccountSnapshot(ACCOUNT_ID, "Y",
            new BigDecimal("1940.00"), new BigDecimal("2020.00"), new BigDecimal("1020.00"));

    private JsonNode body(MvcResult result) throws Exception {
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private void stubCardAndParties(CardSnapshot snapshot) {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(snapshot));
        when(customerClient.findCustomer(CUSTOMER_ID)).thenReturn(Optional.of(new CustomerSnapshot(CUSTOMER_ID)));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account));
    }

    private String authorizationRequest(String amount, String transactionId) {
        return """
                {
                  "cardNumber": "%s",
                  "transactionAmount": %s,
                  "authType": "01",
                  "cardExpiryDate": "2805",
                  "messageType": "0100",
                  "messageSource": "POS",
                  "processingCode": "000000",
                  "merchantCategoryCode": "5411",
                  "acquirerCountryCode": "USA",
                  "posEntryMode": 5,
                  "merchantId": "MERCHANT0000001",
                  "merchantName": "Corner Grocery",
                  "merchantCity": "Springfield",
                  "merchantState": "IL",
                  "merchantZip": "62704",
                  "transactionId": "%s",
                  "authTimestamp": "2026-10-25T10:15:00"
                }
                """.formatted(CARD_NUMBER, amount, transactionId);
    }

    private MvcResult authorize(String amount, String transactionId) throws Exception {
        return mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest(amount, transactionId)))
                .andExpect(status().isCreated())
                .andReturn();
    }

    @Test
    void approvesAuthorizationAndCreatesPendingSummary() throws Exception {
        stubCardAndParties(card);

        MvcResult result = mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest("50.00", "TXN000000000001")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.authorizationId").isNotEmpty())
                .andExpect(jsonPath("$.cardNumber").value(CARD_NUMBER))
                .andExpect(jsonPath("$.transactionId").value("TXN000000000001"))
                .andExpect(jsonPath("$.authTimestamp").value("2026-10-25T10:15:00"))
                .andExpect(jsonPath("$.responseCode").value("00"))
                .andExpect(jsonPath("$.reasonCode").value("0000"))
                .andExpect(jsonPath("$.accountId").value(ACCOUNT_ID))
                .andExpect(jsonPath("$.customerId").value(CUSTOMER_ID))
                .andExpect(jsonPath("$.fraudFlag").value("N"))
                .andReturn();

        assertThat(body(result).get("approvedAmount").decimalValue()).isEqualByComparingTo("50.00");

        mockMvc.perform(get("/api/v1/pending-authorizations/" + ACCOUNT_ID))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.accountId").value(ACCOUNT_ID))
                .andExpect(jsonPath("$.approvedCount").value(1))
                .andExpect(jsonPath("$.declinedCount").value(0));
    }

    @Test
    void declinesWith4100WhenAmountExceedsAvailableCredit() throws Exception {
        stubCardAndParties(card);

        MvcResult result = mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest("500.00", "TXN000000000002")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.responseCode").value("05"))
                .andExpect(jsonPath("$.reasonCode").value("4100"))
                .andReturn();

        assertThat(body(result).get("approvedAmount").decimalValue()).isEqualByComparingTo("0.00");

        MvcResult pending = mockMvc.perform(get("/api/v1/pending-authorizations/" + ACCOUNT_ID))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.declinedCount").value(1))
                .andExpect(jsonPath("$.approvedCount").value(0))
                .andReturn();
        assertThat(body(pending).get("declinedAmount").decimalValue()).isEqualByComparingTo("500.00");
        assertThat(body(pending).get("creditBalance").decimalValue()).isEqualByComparingTo("0.00");
    }

    @Test
    void declinesWith3100AndDoesNotPersistWhenCardDoesNotExist() throws Exception {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.empty());

        mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest("120.00", "TXN000000000003")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.responseCode").value("05"))
                .andExpect(jsonPath("$.reasonCode").value("3100"));

        mockMvc.perform(get("/api/v1/authorizations").param("accountId", ACCOUNT_ID))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.total").value(0))
                .andExpect(jsonPath("$.items.length()").value(0));

        assertThat(authorizations.countAuthorizations()).isZero();

        mockMvc.perform(get("/api/v1/pending-authorizations/" + ACCOUNT_ID))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("AUTHORIZATION_SUMMARY_NOT_FOUND"));
    }

    @Test
    void declinesWith4200WhenCardIsNotActive() throws Exception {
        stubCardAndParties(new CardSnapshot(CARD_NUMBER, ACCOUNT_ID, CUSTOMER_ID, "N",
                LocalDate.of(2028, 5, 20)));

        mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest("50.00", "TXN000000000004")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.responseCode").value("05"))
                .andExpect(jsonPath("$.reasonCode").value("4200"));
    }

    @Test
    void declinesWith5100AfterCardIsFlaggedForFraud() throws Exception {
        stubCardAndParties(card);

        MvcResult approved = authorize("50.00", "TXN000000000005");
        String authorizationId = body(approved).get("authorizationId").asText();
        assertThat(body(approved).get("responseCode").asText()).isEqualTo("00");

        mockMvc.perform(post("/api/v1/authorizations/" + authorizationId + "/fraud"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.authorizationId").value(authorizationId))
                .andExpect(jsonPath("$.fraudFlag").value("Y"))
                .andExpect(jsonPath("$.cardNumber").value(CARD_NUMBER))
                .andExpect(jsonPath("$.cardBlocked").value(true));

        mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest("20.00", "TXN000000000006")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.responseCode").value("05"))
                .andExpect(jsonPath("$.reasonCode").value("5100"));

        mockMvc.perform(get("/api/v1/authorizations/" + authorizationId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.fraudFlag").value("Y"))
                .andExpect(jsonPath("$.accountId").value(ACCOUNT_ID))
                .andExpect(jsonPath("$.merchantName").value("Corner Grocery"));
    }

    @Test
    void purgesExpiredDetailsAndReleasesCreditBalance() throws Exception {
        stubCardAndParties(card);
        MvcResult approved = authorize("50.00", "TXN000000000007");
        assertThat(body(approved).get("responseCode").asText()).isEqualTo("00");

        // 模拟 10 天前的批准授权：明细直接落库，并同步占用汇总的信用余额
        AuthorizationCase expired = new AuthorizationCase(new AuthorizationRequest(CARD_NUMBER,
                LocalDateTime.now().minusDays(10), new BigDecimal("100.00"), "01", "2805", "0100", "POS",
                "000000", "5411", "USA", 5, "MERCHANT0000001", "Corner Grocery", "Springfield", "IL",
                "62704", "TXN000000000008", ACCOUNT_ID, CUSTOMER_ID));
        expired.decide("00", "0000", new BigDecimal("100.00"));
        authorizations.saveAuthorization(expired);

        AuthorizationSummary summary = summaries.findSummary(ACCOUNT_ID).orElseThrow();
        summary.applyApproved(new BigDecimal("100.00"));
        summaries.saveSummary(summary);
        assertThat(summary.getCreditBalance()).isEqualByComparingTo("150.00");

        MvcResult purged = mockMvc.perform(post("/api/v1/authorization-purges")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"expiryDays\": 5}"))
                .andExpect(status().isOk())
                .andReturn();

        JsonNode body = body(purged);
        assertThat(body.get("detailsRead").asInt()).isGreaterThanOrEqualTo(1);
        assertThat(body.get("detailsDeleted").asInt()).isGreaterThanOrEqualTo(1);
        assertThat(body.get("creditBalanceReleased").decimalValue()).isEqualByComparingTo("100.00");

        AuthorizationSummary refreshed = summaries.findSummary(ACCOUNT_ID).orElseThrow();
        assertThat(refreshed.getCreditBalance()).isEqualByComparingTo("50.00");
        assertThat(refreshed.getApprovedCount()).isEqualTo(1);
        assertThat(refreshed.getApprovedAmount()).isEqualByComparingTo("50.00");
        assertThat(authorizations.findAuthorization(expired.getAuthorizationId())).isEmpty();
        assertThat(authorizations.countAuthorizations()).isEqualTo(1);
    }

    @Test
    void returns404ForUnknownAuthorization() throws Exception {
        mockMvc.perform(get("/api/v1/authorizations/does-not-exist"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("AUTHORIZATION_NOT_FOUND"));

        mockMvc.perform(post("/api/v1/authorizations/does-not-exist/fraud"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("AUTHORIZATION_NOT_FOUND"));
    }

    @Test
    void rejectsInvalidAuthorizationRequest() throws Exception {
        mockMvc.perform(post("/api/v1/authorizations")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(authorizationRequest("-1.00", "TXN000000000009")))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));

        mockMvc.perform(post("/api/v1/authorization-purges")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"expiryDays\": 500}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));
    }
}

