package com.carddemo.iam.application;

import com.carddemo.iam.domain.exception.UnauthorizedException;
import com.carddemo.iam.domain.security.TokenVerification;
import com.carddemo.iam.infrastructure.security.HmacTokenService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;

import java.time.Instant;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * 登录用例：种子凭据可通过 PBKDF2 校验并签发 token（H2 + Flyway 种子）。
 */
@SpringBootTest
@ActiveProfiles("test")
class AuthenticationServiceTest {

    @Autowired
    private AuthenticationService authenticationService;

    @Test
    void logsInWithSeededAdministratorCredentials() {
        LoginResult result = authenticationService.login("ADMIN001", "admin123");

        assertThat(result.token()).isNotBlank().contains(".");
        assertThat(result.expiresAt()).isAfter(Instant.now());
        assertThat(result.user().getUserId()).isEqualTo("ADMIN001");
        assertThat(result.user().getUserType()).isEqualTo("A");
        assertThat(result.user().landingMenu()).isEqualTo("ADMIN");
        assertThat(result.user().getPasswordHash()).startsWith("pbkdf2$210000$");
    }

    @Test
    void logsInWithSeededUserCredentialsAndLandsOnUserMenu() {
        LoginResult result = authenticationService.login("USER0001", "user1234");

        assertThat(result.user().landingMenu()).isEqualTo("USER");
        assertThat(result.user().getUserType()).isEqualTo("U");
    }

    @Test
    void normalizesUserIdCaseAndWhitespaceButNotPasswordCase() {
        assertThat(authenticationService.login(" admin001 ", "admin123").user().getUserId())
                .isEqualTo("ADMIN001");

        assertThatThrownBy(() -> authenticationService.login("ADMIN001", "ADMIN123"))
                .isInstanceOf(UnauthorizedException.class)
                .extracting("code").isEqualTo("INVALID_CREDENTIALS");
    }

    @Test
    void rejectsWrongPasswordWithInvalidCredentials() {
        assertThatThrownBy(() -> authenticationService.login("ADMIN001", "wrong-pass"))
                .isInstanceOf(UnauthorizedException.class)
                .extracting("code").isEqualTo("INVALID_CREDENTIALS");
    }

    @Test
    void hidesUnknownUserBehindSameError() {
        assertThatThrownBy(() -> authenticationService.login("NOBODY01", "admin123"))
                .isInstanceOf(UnauthorizedException.class)
                .extracting("code").isEqualTo("INVALID_CREDENTIALS");
    }

    @Test
    void verifiesIssuedToken() {
        String token = authenticationService.login("ADMIN001", "admin123").token();

        TokenVerification verification = authenticationService.verify(token);

        assertThat(verification.valid()).isTrue();
        assertThat(verification.userId()).isEqualTo("ADMIN001");
        assertThat(verification.userType()).isEqualTo("A");
        assertThat(verification.expiresAt()).isAfter(Instant.now());
    }

    @Test
    void rejectsTamperedTokenWithoutThrowing() {
        String token = authenticationService.login("ADMIN001", "admin123").token();
        String tampered = token.substring(0, token.indexOf('.') + 1) + "AAAA";

        assertThat(authenticationService.verify(tampered).valid()).isFalse();
        assertThat(authenticationService.verify("garbage").valid()).isFalse();
        assertThat(authenticationService.verify(null).valid()).isFalse();
    }

    @Test
    void rejectsExpiredTokenWithoutThrowing() {
        HmacTokenService expiring = new HmacTokenService("carddemo-demo-secret-change-me", -10);
        String expired = expiring.issue("ADMIN001", "A").value();

        TokenVerification verification = expiring.verify(expired);

        assertThat(verification.valid()).isFalse();
        assertThat(verification.userId()).isNull();
    }
}

package com.carddemo.iam.application;

import com.carddemo.iam.domain.exception.BusinessRuleException;
import com.carddemo.iam.domain.exception.NotFoundException;
import com.carddemo.iam.domain.exception.ValidationException;
import com.carddemo.iam.domain.model.User;
import com.carddemo.iam.domain.model.UserDetails;
import com.carddemo.iam.domain.security.PasswordHasher;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * 用户目录用例：列表、新增、修改、删除与管理员保护规则。
 */
@SpringBootTest
@ActiveProfiles("test")
@Transactional
class UserDirectoryServiceTest {

    @Autowired
    private UserDirectoryService userDirectoryService;

    @Autowired
    private PasswordHasher passwordHasher;

    @Test
    void listsSeededUsersSortedByUserId() {
        PageResult<User> page = userDirectoryService.list(0, 10);

        assertThat(page.items()).extracting(User::getUserId)
                .containsExactly("ADMIN001", "USER0001");
        assertThat(page.page()).isZero();
        assertThat(page.size()).isEqualTo(10);
        assertThat(page.total()).isEqualTo(2);
    }

    @Test
    void returns404ForUnknownUser() {
        assertThatThrownBy(() -> userDirectoryService.get("NOBODY01"))
                .isInstanceOf(NotFoundException.class)
                .extracting("code").isEqualTo("USER_NOT_FOUND");
    }

    @Test
    void createsUserWithUppercasedIdAndHashedPassword() {
        User created = userDirectoryService.create(" user0002 ",
                new UserDetails("Ada", "Lovelace", "U"), "pass1234");

        assertThat(created.getUserId()).isEqualTo("USER0002");
        assertThat(created.getUserType()).isEqualTo("U");
        assertThat(created.getPasswordHash()).startsWith("pbkdf2$210000$");
        assertThat(passwordHasher.verify("pass1234", created.getPasswordHash())).isTrue();
        assertThat(userDirectoryService.list(0, 10).total()).isEqualTo(3);
    }

    @Test
    void rejectsDuplicateUserId() {
        assertThatThrownBy(() -> userDirectoryService.create("admin001",
                new UserDetails("Other", "Admin", "A"), "pass1234"))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("USER_ALREADY_EXISTS");
    }

    @Test
    void rejectsUserTypeOutsideLegacyEnumeration() {
        assertThatThrownBy(() -> userDirectoryService.create("USER0003",
                new UserDetails("Ada", "Lovelace", "X"), "pass1234"))
                .isInstanceOf(ValidationException.class)
                .hasMessageContaining("User Type must be A or U");
    }

    @Test
    void rejectsBlankFirstName() {
        assertThatThrownBy(() -> userDirectoryService.create("USER0004",
                new UserDetails("  ", "Lovelace", "U"), "pass1234"))
                .isInstanceOf(ValidationException.class)
                .extracting("details")
                .isEqualTo(List.of("firstName: First Name must be supplied."));
    }

    @Test
    void rejectsPasswordOutsideLegacyLengthRange() {
        assertThatThrownBy(() -> userDirectoryService.create("USER0005",
                new UserDetails("Ada", "Lovelace", "U"), "short"))
                .isInstanceOf(ValidationException.class)
                .hasMessage("Password must be 8 to 64 characters.");
    }

    @Test
    void refusesToDeleteLastAdministrator() {
        assertThatThrownBy(() -> userDirectoryService.delete("ADMIN001", "USER0001"))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("LAST_ADMIN");
    }

    @Test
    void refusesToDemoteLastAdministrator() {
        assertThatThrownBy(() -> userDirectoryService.update("ADMIN001",
                new UserDetails("System", "Administrator", "U"), null))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("LAST_ADMIN");
    }

    @Test
    void refusesToDeleteOwnRecord() {
        assertThatThrownBy(() -> userDirectoryService.delete("USER0001", " user0001 "))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("CANNOT_DELETE_SELF");
    }

    @Test
    void keepsPasswordWhenUpdateOmitsItAndReplacesItWhenSupplied() {
        User before = userDirectoryService.get("USER0001");
        String originalHash = before.getPasswordHash();

        User renamed = userDirectoryService.update("USER0001",
                new UserDetails("Demo", "Tester", "U"), null);

        assertThat(renamed.getLastName()).isEqualTo("Tester");
        assertThat(renamed.getPasswordHash()).isEqualTo(originalHash);

        User repasswored = userDirectoryService.update("USER0001",
                new UserDetails("Demo", "Tester", "U"), "newpass1");

        assertThat(repasswored.getPasswordHash()).isNotEqualTo(originalHash);
        assertThat(passwordHasher.verify("newpass1", repasswored.getPasswordHash())).isTrue();
    }

    @Test
    void deletesAdministratorOnceAnotherAdministratorExists() {
        userDirectoryService.update("USER0001", new UserDetails("Demo", "User", "A"), null);

        userDirectoryService.delete("ADMIN001", "USER0001");

        assertThatThrownBy(() -> userDirectoryService.get("ADMIN001"))
                .isInstanceOf(NotFoundException.class);
    }
}

package com.carddemo.iam.infrastructure.security;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class Pbkdf2PasswordHasherTest {

    private final Pbkdf2PasswordHasher hasher = new Pbkdf2PasswordHasher();

    @Test
    void hashesWithAdr008FormatAndNeverRevealsPlaintext() {
        String encoded = hasher.hash("admin123");

        assertThat(encoded).startsWith("pbkdf2$210000$").doesNotContain("admin123");
        assertThat(encoded).isNotEqualTo(hasher.hash("admin123"));
    }

    @Test
    void verifiesOnlyTheMatchingPassword() {
        String encoded = hasher.hash("user1234");

        assertThat(hasher.verify("user1234", encoded)).isTrue();
        assertThat(hasher.verify("user1235", encoded)).isFalse();
        assertThat(hasher.verify("USER1234", encoded)).isFalse();
        assertThat(hasher.verify("user1234", "not-a-hash")).isFalse();
        assertThat(hasher.verify(null, encoded)).isFalse();
    }
}

