package com.carddemo.marketing.application;

import com.carddemo.marketing.domain.exception.RemoteServiceException;
import com.carddemo.marketing.domain.model.AccountSnapshot;
import com.carddemo.marketing.domain.model.Campaign;
import com.carddemo.marketing.domain.model.CampaignDraft;
import com.carddemo.marketing.domain.model.CampaignType;
import com.carddemo.marketing.domain.model.Enrollment;
import com.carddemo.marketing.domain.model.RewardGrant;
import com.carddemo.marketing.domain.model.RewardStatus;
import com.carddemo.marketing.domain.repository.CampaignRepository;
import com.carddemo.marketing.domain.repository.EnrollmentRepository;
import com.carddemo.marketing.domain.repository.RewardGrantRepository;
import com.carddemo.marketing.infrastructure.client.AccountClient;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class RewardEvaluationServiceTest {

    private static final String CARD = "0500024453765740";
    private static final String ACCOUNT = "00000000001";
    private static final String CUSTOMER = "000000001";
    private static final LocalDateTime NOW = LocalDateTime.of(2026, 10, 25, 10, 0);
    private static final Clock CLOCK = Clock.fixed(Instant.parse("2026-10-25T10:00:00Z"), ZoneOffset.UTC);

    @Mock
    private CampaignRepository campaigns;
    @Mock
    private EnrollmentRepository enrollments;
    @Mock
    private RewardGrantRepository rewards;
    @Mock
    private AccountClient accountClient;

    private RewardEvaluationService service;
    private Campaign campaign;

    @BeforeEach
    void setUp() {
        service = new RewardEvaluationService(campaigns, enrollments, rewards, accountClient, CLOCK);
        CampaignDraft draft = new CampaignDraft("餐饮返现", null, CampaignType.CATEGORY_CASHBACK,
                NOW.minusDays(10), NOW.plusDays(10), null, "0001",
                new BigDecimal("50.00"), new BigDecimal("0.0500"), null,
                new BigDecimal("30.00"), 5, new BigDecimal("1000.00"), null, true);
        campaign = new Campaign("c1", draft, NOW);
        campaign.activate(NOW);
    }

    private EvaluationCommand command() {
        return new EvaluationCommand("0000000000000901", CARD, ACCOUNT, CUSTOMER,
                new BigDecimal("120.00"), "0001", "01", "Dinner", NOW);
    }

    private void stubHappyPath() {
        when(accountClient.findAccount(ACCOUNT)).thenReturn(Optional.of(
                new AccountSnapshot(ACCOUNT, "Y", new BigDecimal("1940.00"), "A000000000")));
        when(campaigns.findActiveAt(any())).thenReturn(List.of(campaign));
        when(rewards.existsByCampaignAndTransaction("c1", "0000000000000901")).thenReturn(false);
        when(enrollments.findEnrollment("c1", CARD)).thenReturn(Optional.of(
                new Enrollment("e1", "c1", CARD, ACCOUNT, CUSTOMER, NOW)));
        when(rewards.countByCampaignAndCard("c1", CARD)).thenReturn(0L);
    }

    @Test
    void grantsCashbackAndCallsAccount() {
        stubHappyPath();

        EvaluationOutcome outcome = service.evaluate(command());

        assertThat(outcome.grants()).hasSize(1);
        RewardGrant grant = outcome.grants().get(0).grant();
        assertThat(grant.getStatus()).isEqualTo(RewardStatus.GRANTED);
        assertThat(grant.getRewardAmount()).isEqualByComparingTo("6.00");
        assertThat(campaign.getConsumedAmount()).isEqualByComparingTo("6.00");
        verify(accountClient).creditCashback(eq(ACCOUNT), eq(grant.getRewardId()), eq("c1"),
                eq(new BigDecimal("6.00")));
        verify(rewards).saveReward(grant);
    }

    @Test
    void keepsPendingWhenAccountUnavailable() {
        stubHappyPath();
        doThrow(new RemoteServiceException("account-service is unavailable"))
                .when(accountClient).creditCashback(anyString(), anyString(), anyString(), any());

        EvaluationOutcome outcome = service.evaluate(command());

        RewardGrant grant = outcome.grants().get(0).grant();
        assertThat(grant.getStatus()).isEqualTo(RewardStatus.PENDING);
        assertThat(grant.getFailureReason()).contains("account-service");
        verify(rewards).saveReward(grant);
    }

    @Test
    void isIdempotentPerCampaignAndTransaction() {
        when(accountClient.findAccount(ACCOUNT)).thenReturn(Optional.of(
                new AccountSnapshot(ACCOUNT, "Y", new BigDecimal("1940.00"), "A000000000")));
        when(campaigns.findActiveAt(any())).thenReturn(List.of(campaign));
        when(rewards.existsByCampaignAndTransaction("c1", "0000000000000901")).thenReturn(true);

        EvaluationOutcome outcome = service.evaluate(command());

        assertThat(outcome.grants()).isEmpty();
        assertThat(outcome.skipped()).extracting(EvaluationOutcome.Skipped::reason)
                .containsExactly("ALREADY_EVALUATED");
        verify(rewards, never()).saveReward(any());
    }

    @Test
    void skipsWhenNotEnrolled() {
        when(accountClient.findAccount(ACCOUNT)).thenReturn(Optional.of(
                new AccountSnapshot(ACCOUNT, "Y", new BigDecimal("1940.00"), "A000000000")));
        when(campaigns.findActiveAt(any())).thenReturn(List.of(campaign));
        when(rewards.existsByCampaignAndTransaction("c1", "0000000000000901")).thenReturn(false);
        when(enrollments.findEnrollment("c1", CARD)).thenReturn(Optional.empty());
        when(rewards.countByCampaignAndCard("c1", CARD)).thenReturn(0L);

        EvaluationOutcome outcome = service.evaluate(command());

        assertThat(outcome.grants()).isEmpty();
        assertThat(outcome.skipped()).extracting(EvaluationOutcome.Skipped::reason)
                .containsExactly("NOT_ENROLLED");
        verify(accountClient, never()).creditCashback(anyString(), anyString(), anyString(), any());
    }

    @Test
    void fulfilsPendingCashback() {
        RewardGrant pending = new RewardGrant("r1", "c1", "0000000000000901", CARD, ACCOUNT, CUSTOMER,
                com.carddemo.marketing.domain.model.RewardComputation.cashback(new BigDecimal("6.00")), NOW);
        pending.markPending("account-service is unavailable");
        when(rewards.findReward("r1")).thenReturn(Optional.of(pending));
        when(campaigns.findCampaign("c1")).thenReturn(Optional.of(campaign));

        RewardView view = service.fulfill("r1");

        assertThat(view.grant().getStatus()).isEqualTo(RewardStatus.GRANTED);
        assertThat(view.campaignName()).isEqualTo("餐饮返现");
        verify(rewards).saveReward(pending);
    }

    @Test
    void argumentCaptorKeepsGrantAmount() {
        stubHappyPath();
        service.evaluate(command());

        ArgumentCaptor<RewardGrant> captor = ArgumentCaptor.forClass(RewardGrant.class);
        verify(rewards).saveReward(captor.capture());
        assertThat(captor.getValue().getRewardPoints()).isZero();
        assertThat(captor.getValue().getAccountId()).isEqualTo(ACCOUNT);
    }
}

package com.carddemo.marketing.domain.model;

import com.carddemo.marketing.domain.exception.BusinessRuleException;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class CampaignTest {

    private static final LocalDateTime NOW = LocalDateTime.of(2026, 10, 25, 10, 0);

    static CampaignDraft cashbackDraft() {
        return new CampaignDraft("餐饮返现", "测试", CampaignType.CATEGORY_CASHBACK,
                NOW.minusDays(1), NOW.plusDays(30), null, "0001",
                new BigDecimal("50.00"), new BigDecimal("0.0500"), null,
                new BigDecimal("30.00"), 5, new BigDecimal("1000.00"), null, true);
    }

    @Test
    void createsDraftAndConsumesBudget() {
        Campaign campaign = new Campaign("c1", cashbackDraft(), NOW);

        assertThat(campaign.getStatus()).isEqualTo(CampaignStatus.DRAFT);
        assertThat(campaign.getConsumedAmount()).isEqualByComparingTo("0.00");
        assertThat(campaign.remainingBudget()).isEqualByComparingTo("1000.00");

        campaign.activate(NOW);
        campaign.consumeCashback(new BigDecimal("30.00"));

        assertThat(campaign.getStatus()).isEqualTo(CampaignStatus.ACTIVE);
        assertThat(campaign.getConsumedAmount()).isEqualByComparingTo("30.00");
        assertThat(campaign.remainingBudget()).isEqualByComparingTo("970.00");
    }

    @Test
    void budgetCannotBeExceeded() {
        Campaign campaign = new Campaign("c1", cashbackDraft(), NOW);
        campaign.activate(NOW);

        assertThatThrownBy(() -> campaign.consumeCashback(new BigDecimal("1000.01")))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("BUDGET_EXHAUSTED");
    }

    @Test
    void stateMachineOnlyAllowsLegalTransitions() {
        Campaign campaign = new Campaign("c1", cashbackDraft(), NOW);

        assertThatThrownBy(() -> campaign.pause(NOW))
                .isInstanceOf(BusinessRuleException.class);
        campaign.activate(NOW);
        assertThatThrownBy(() -> campaign.activate(NOW))
                .isInstanceOf(BusinessRuleException.class);
        campaign.pause(NOW);
        campaign.activate(NOW);
        campaign.end(NOW);
        assertThat(campaign.getStatus()).isEqualTo(CampaignStatus.ENDED);
        assertThatThrownBy(() -> campaign.activate(NOW))
                .isInstanceOf(BusinessRuleException.class);
    }

    @Test
    void cannotEditActiveCampaign() {
        Campaign campaign = new Campaign("c1", cashbackDraft(), NOW);
        campaign.activate(NOW);

        assertThatThrownBy(() -> campaign.applyDraft(cashbackDraft(), NOW))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("CAMPAIGN_NOT_EDITABLE");
    }

    @Test
    void rejectsInvalidPeriodAndMissingReward() {
        CampaignDraft badPeriod = new CampaignDraft("x", null, CampaignType.CATEGORY_CASHBACK,
                NOW, NOW.minusDays(1), null, "0001", BigDecimal.ZERO,
                new BigDecimal("0.05"), null, null, 1, new BigDecimal("100"), null, true);
        assertThatThrownBy(() -> new Campaign("c1", badPeriod, NOW))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("INVALID_CAMPAIGN_PERIOD");

        CampaignDraft noReward = new CampaignDraft("x", null, CampaignType.CATEGORY_CASHBACK,
                NOW.minusDays(1), NOW.plusDays(1), null, "0001", BigDecimal.ZERO,
                null, null, null, 1, new BigDecimal("100"), null, true);
        assertThatThrownBy(() -> new Campaign("c1", noReward, NOW))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("INVALID_CAMPAIGN_RULE");
    }

    @Test
    void rejectsCashbackWithoutBudget() {
        CampaignDraft draft = new CampaignDraft("x", null, CampaignType.CATEGORY_CASHBACK,
                NOW.minusDays(1), NOW.plusDays(1), null, "0001", BigDecimal.ZERO,
                new BigDecimal("0.05"), null, null, 1, BigDecimal.ZERO, null, true);
        assertThatThrownBy(() -> new Campaign("c1", draft, NOW))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("BUDGET_REQUIRED");
    }
}

package com.carddemo.marketing.domain.service;

import com.carddemo.marketing.domain.model.AccountSnapshot;
import com.carddemo.marketing.domain.model.Campaign;
import com.carddemo.marketing.domain.model.CampaignDraft;
import com.carddemo.marketing.domain.model.CampaignType;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import static org.assertj.core.api.Assertions.assertThat;

class EligibilityPolicyTest {

    private static final LocalDateTime NOW = LocalDateTime.of(2026, 10, 25, 10, 0);
    private static final AccountSnapshot ACCOUNT = new AccountSnapshot("00000000001", "Y",
            new BigDecimal("1940.00"), "A000000000");

    private Campaign campaign(CampaignType type, String category, BigDecimal min,
                             BigDecimal rate, BigDecimal fixed, BigDecimal budget,
                             boolean enrollmentRequired, int maxPerCard) {
        CampaignDraft draft = new CampaignDraft("测试", null, type,
                NOW.minusDays(10), NOW.plusDays(10), null, category, min,
                rate, fixed, new BigDecimal("50.00"), maxPerCard, budget, null, enrollmentRequired);
        Campaign campaign = new Campaign("c1", draft, NOW);
        campaign.activate(NOW);
        return campaign;
    }

    private Campaign categoryCampaign() {
        return campaign(CampaignType.CATEGORY_CASHBACK, "0001", new BigDecimal("50.00"),
                new BigDecimal("0.05"), null, new BigDecimal("1000.00"), true, 5);
    }

    @Test
    void eligibleWhenAllConditionsMet() {
        EligibilityPolicy.Evaluation evaluation = EligibilityPolicy.evaluateTransaction(
                categoryCampaign(), ACCOUNT, new BigDecimal("120.00"), "0001", true, 0, NOW);

        assertThat(evaluation.eligible()).isTrue();
        assertThat(evaluation.reward().amount()).isEqualByComparingTo("6.00");
    }

    @Test
    void rejectsNotActiveCampaign() {
        Campaign campaign = new Campaign("c1", new CampaignDraft("测试", null,
                CampaignType.CATEGORY_CASHBACK, NOW.minusDays(1), NOW.plusDays(1), null, "0001",
                BigDecimal.ZERO, new BigDecimal("0.05"), null, null, 1, new BigDecimal("100"),
                null, true), NOW);

        assertThat(EligibilityPolicy.evaluateParticipation(campaign, ACCOUNT, true, NOW).reason())
                .isEqualTo(EligibilityPolicy.NOT_ACTIVE);
    }

    @Test
    void rejectsInactiveAccountAndGroupMismatch() {
        AccountSnapshot inactive = new AccountSnapshot("00000000001", "N",
                BigDecimal.ZERO, "A000000000");
        assertThat(EligibilityPolicy.evaluateParticipation(categoryCampaign(), inactive, true, NOW).reason())
                .isEqualTo(EligibilityPolicy.ACCOUNT_INACTIVE);

        AccountSnapshot otherGroup = new AccountSnapshot("00000000001", "Y",
                BigDecimal.ZERO, "B000000000");
        Campaign targeted = new Campaign("c2", new CampaignDraft("测试", null,
                CampaignType.CATEGORY_CASHBACK, NOW.minusDays(1), NOW.plusDays(1), "A000000000",
                "0001", BigDecimal.ZERO, new BigDecimal("0.05"), null, null, 1,
                new BigDecimal("100"), null, true), NOW);
        targeted.activate(NOW);
        assertThat(EligibilityPolicy.evaluateParticipation(targeted, otherGroup, true, NOW).reason())
                .isEqualTo(EligibilityPolicy.GROUP_MISMATCH);
    }

    @Test
    void rejectsWrongCategoryOrAmount() {
        assertThat(EligibilityPolicy.evaluateTransaction(categoryCampaign(), ACCOUNT,
                new BigDecimal("120.00"), "0002", true, 0, NOW).reason())
                .isEqualTo(EligibilityPolicy.CATEGORY_MISMATCH);
        assertThat(EligibilityPolicy.evaluateTransaction(categoryCampaign(), ACCOUNT,
                new BigDecimal("49.99"), "0001", true, 0, NOW).reason())
                .isEqualTo(EligibilityPolicy.AMOUNT_TOO_LOW);
    }

    @Test
    void rejectsWhenNotEnrolledOrLimitReached() {
        assertThat(EligibilityPolicy.evaluateTransaction(categoryCampaign(), ACCOUNT,
                new BigDecimal("120.00"), "0001", false, 0, NOW).reason())
                .isEqualTo(EligibilityPolicy.NOT_ENROLLED);
        assertThat(EligibilityPolicy.evaluateTransaction(categoryCampaign(), ACCOUNT,
                new BigDecimal("120.00"), "0001", true, 5, NOW).reason())
                .isEqualTo(EligibilityPolicy.CARD_LIMIT_REACHED);
    }

    @Test
    void rejectsFirstPurchaseWhenAlreadyRewarded() {
        Campaign first = campaign(CampaignType.FIRST_PURCHASE_CASHBACK, null,
                new BigDecimal("100.00"), null, new BigDecimal("20.00"),
                new BigDecimal("1000.00"), false, 2);

        assertThat(EligibilityPolicy.evaluateTransaction(first, ACCOUNT,
                new BigDecimal("150.00"), "0001", false, 1, NOW).reason())
                .isEqualTo(EligibilityPolicy.ALREADY_REWARDED);
    }

    @Test
    void rejectsWhenBudgetExhausted() {
        Campaign campaign = campaign(CampaignType.CATEGORY_CASHBACK, "0001",
                new BigDecimal("50.00"), new BigDecimal("0.05"), null,
                new BigDecimal("5.00"), false, 5);

        assertThat(EligibilityPolicy.evaluateTransaction(campaign, ACCOUNT,
                new BigDecimal("120.00"), "0001", false, 0, NOW).reason())
                .isEqualTo(EligibilityPolicy.BUDGET_EXHAUSTED);
    }
}

package com.carddemo.marketing.domain.service;

import com.carddemo.marketing.domain.model.Campaign;
import com.carddemo.marketing.domain.model.CampaignDraft;
import com.carddemo.marketing.domain.model.CampaignType;
import com.carddemo.marketing.domain.model.RewardComputation;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import static org.assertj.core.api.Assertions.assertThat;

class RewardCalculatorTest {

    private static final LocalDateTime NOW = LocalDateTime.of(2026, 10, 25, 10, 0);

    private Campaign campaign(CampaignType type, BigDecimal rate, BigDecimal fixed,
                              BigDecimal maxPerTxn, BigDecimal multiplier) {
        CampaignDraft draft = new CampaignDraft("测试", null, type,
                NOW.minusDays(1), NOW.plusDays(1), null, null, BigDecimal.ZERO,
                rate, fixed, maxPerTxn, 3, new BigDecimal("1000.00"), multiplier, false);
        return new Campaign("c1", draft, NOW);
    }

    @Test
    void fixedRewardWins() {
        RewardComputation reward = RewardCalculator.compute(
                campaign(CampaignType.FIRST_PURCHASE_CASHBACK, null, new BigDecimal("20.00"), null, null),
                new BigDecimal("150.00"));

        assertThat(reward.amount()).isEqualByComparingTo("20.00");
        assertThat(reward.points()).isZero();
    }

    @Test
    void rateIsRoundedAndCapped() {
        Campaign campaign = campaign(CampaignType.CATEGORY_CASHBACK, new BigDecimal("0.0500"),
                null, new BigDecimal("30.00"), null);

        assertThat(RewardCalculator.compute(campaign, new BigDecimal("120.00")).amount())
                .isEqualByComparingTo("6.00");
        assertThat(RewardCalculator.compute(campaign, new BigDecimal("1000.00")).amount())
                .isEqualByComparingTo("30.00");
        assertThat(RewardCalculator.compute(campaign, new BigDecimal("50.55")).amount())
                .isEqualByComparingTo("2.53");
    }

    @Test
    void pointsUseFloorMultiplication() {
        RewardComputation reward = RewardCalculator.compute(
                campaign(CampaignType.POINTS_MULTIPLIER, null, null, null, new BigDecimal("2.00")),
                new BigDecimal("120.75"));

        assertThat(reward.points()).isEqualTo(241);
        assertThat(reward.amount()).isEqualByComparingTo("0.00");
    }
}

package com.carddemo.marketing.interfaces.rest;

import com.carddemo.marketing.domain.model.AccountSnapshot;
import com.carddemo.marketing.infrastructure.client.AccountClient;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.MethodOrderer;
