package com.carddemo.transaction.application;

import com.carddemo.transaction.domain.exception.BusinessRuleException;
import com.carddemo.transaction.domain.model.AccountSnapshot;
import com.carddemo.transaction.domain.model.CardSnapshot;
import com.carddemo.transaction.domain.model.TransactionRecord;
import com.carddemo.transaction.domain.model.TransactionStatus;
import com.carddemo.transaction.domain.repository.TransactionRepository;
import com.carddemo.transaction.infrastructure.client.AccountClient;
import com.carddemo.transaction.infrastructure.client.CardClient;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * 账单支付用例：BR-BILL-01（无欠款拒绝）、BR-BILL-03/04（全额还款并落交易）、BR-BILL-05（下游成功才 POSTED）。
 */
@SpringBootTest
@ActiveProfiles("test")
@Transactional
class BillPaymentServiceTest {

    private static final String ACCOUNT_ID = "00000000002";

    @Autowired
    private BillPaymentService billPaymentService;

    @Autowired
    private TransactionRepository transactions;

    @MockBean
    private AccountClient accountClient;

    @MockBean
    private CardClient cardClient;

    private final CardSnapshot card = new CardSnapshot("0683586198171516", ACCOUNT_ID, "000000002",
            "ENRICO ROSENBAUM", LocalDate.of(2029, 8, 11), "Y");

    private AccountSnapshot account(String balance) {
        return new AccountSnapshot(ACCOUNT_ID, "Y", new BigDecimal(balance), new BigDecimal("6130.00"),
                new BigDecimal("5448.00"), new BigDecimal("0.00"), new BigDecimal("0.00"),
                LocalDate.of(2024, 8, 11), "A000000000");
    }

    @Test
    void rejectsAccountWithNothingToPay() {
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("0.00")));

        assertThatThrownBy(() -> billPaymentService.pay(ACCOUNT_ID, true))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("NOTHING_TO_PAY");
        verify(accountClient, never()).payBill(any(), any());
    }

    @Test
    void paysOutstandingBalanceAndPersistsPostedTransaction() {
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("1580.00")));
        when(cardClient.findCardsByAccount(ACCOUNT_ID)).thenReturn(List.of(card));
        when(accountClient.payBill(ACCOUNT_ID, new BigDecimal("1580.00"))).thenReturn(account("0.00"));

        BillPaymentResult result = billPaymentService.pay(ACCOUNT_ID, true);

        assertThat(result.amount()).isEqualByComparingTo("1580.00");
        assertThat(result.newBalance()).isEqualByComparingTo("0.00");
        assertThat(result.transactionId()).hasSize(16);
        verify(accountClient).payBill(ACCOUNT_ID, new BigDecimal("1580.00"));

        TransactionRecord saved = transactions.findByTransactionId(result.transactionId()).orElseThrow();
        assertThat(saved.getStatus()).isEqualTo(TransactionStatus.POSTED);
        assertThat(saved.getAccountId()).isEqualTo(ACCOUNT_ID);
        assertThat(saved.getCardNumber()).isEqualTo("0683586198171516");
        assertThat(saved.getTypeCode()).isEqualTo("02");
        assertThat(saved.getCategoryCode()).isEqualTo("0002");
        assertThat(saved.getSource()).isEqualTo("POS TERM");
        assertThat(saved.getDescription()).isEqualTo("BILL PAYMENT - ONLINE");
        assertThat(saved.getAmount()).isEqualByComparingTo("1580.00");
        assertThat(saved.getMerchantId()).isEqualTo("999999999");
        assertThat(saved.getMerchantName()).isEqualTo("BILL PAYMENT");
        assertThat(saved.getMerchantCity()).isEqualTo("N/A");
        assertThat(saved.getMerchantZip()).isEqualTo("N/A");
    }

    @Test
    void requiresExplicitConfirmation() {
        assertThatThrownBy(() -> billPaymentService.pay(ACCOUNT_ID, false))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("CONFIRMATION_REQUIRED");
        verify(accountClient, never()).findAccount(any());
        verify(accountClient, never()).payBill(any(), any());
    }

    @Test
    void propagatesDownstreamPaymentFailure() {
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("1580.00")));
        when(cardClient.findCardsByAccount(ACCOUNT_ID)).thenReturn(List.of(card));
        when(accountClient.payBill(ACCOUNT_ID, new BigDecimal("1580.00")))
                .thenThrow(new BusinessRuleException("NOTHING_TO_PAY", "You have nothing to pay..."));

        assertThatThrownBy(() -> billPaymentService.pay(ACCOUNT_ID, true))
                .isInstanceOf(BusinessRuleException.class)
                .extracting("code").isEqualTo("NOTHING_TO_PAY");
    }
}

package com.carddemo.transaction.application;

import com.carddemo.transaction.domain.model.AccountSnapshot;
import com.carddemo.transaction.domain.model.CardSnapshot;
import com.carddemo.transaction.domain.model.TranCategoryBalance;
import com.carddemo.transaction.domain.repository.TranCategoryBalanceRepository;
import com.carddemo.transaction.domain.repository.TransactionRepository;
import com.carddemo.transaction.infrastructure.client.AccountClient;
import com.carddemo.transaction.infrastructure.client.CardClient;
import com.carddemo.transaction.infrastructure.client.MarketingClient;
import com.carddemo.transaction.domain.exception.RemoteServiceException;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * 入账用例：下游服务用 Mockito 替换，本地交易库为真实 H2 + Flyway 种子。
 */
@SpringBootTest
@ActiveProfiles("test")
@Transactional
class PostingServiceTest {

    private static final String CARD_NUMBER = "0500024453765740";
    private static final String ACCOUNT_ID = "00000000001";

    @Autowired
    private PostingService postingService;

    @Autowired
    private TransactionRepository transactions;

    @Autowired
    private TranCategoryBalanceRepository balances;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @MockBean
    private CardClient cardClient;

    @MockBean
    private AccountClient accountClient;

    @MockBean
    private MarketingClient marketingClient;

    private final CardSnapshot card = new CardSnapshot(CARD_NUMBER, ACCOUNT_ID, "000000001",
            "IMMANUEL KESSLER", LocalDate.of(2028, 5, 20), "Y");

    private AccountSnapshot account(String creditLimit) {
        return new AccountSnapshot(ACCOUNT_ID, "Y", new BigDecimal("1940.00"),
                new BigDecimal(creditLimit), new BigDecimal("1020.00"), new BigDecimal("0.00"),
                new BigDecimal("0.00"), LocalDate.of(2028, 5, 20), "A000000000");
    }

    private PostingCommand command(String transactionId, String amount) {
        return new PostingCommand(transactionId, CARD_NUMBER, "01", "0001", "POS TERM",
                "Purchase at Merchant A", new BigDecimal(amount),
                LocalDateTime.of(2026, 10, 25, 10, 15), "800000001", "Merchant A", "Springfield", "10001");
    }

    @Test
    void postedTransactionAccumulatesCategoryBalanceAndCallsAccountService() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("5000.00")));
        when(accountClient.applyPosting(eq(ACCOUNT_ID), any())).thenReturn(account("5000.00"));

        PostingResult result = postingService.post(List.of(command("0000000000000100", "75.00")));

        assertThat(result.status()).isEqualTo("COMPLETED");
        assertThat(result.processed()).isEqualTo(1);
        assertThat(result.posted()).isEqualTo(1);
        assertThat(result.rejected()).isZero();
        assertThat(result.rejections()).isEmpty();

        verify(accountClient).applyPosting(ACCOUNT_ID, new BigDecimal("75.00"));
        verify(marketingClient).evaluateRewards(any());
        assertThat(transactions.findByTransactionId("0000000000000100")).isPresent();
        assertThat(balances.find(ACCOUNT_ID, "01", "0001")).get()
                .extracting(TranCategoryBalance::getBalance)
                .isEqualTo(new BigDecimal("1275.00"));
        assertThat(dailyStatus("0000000000000100")).isEqualTo("POSTED");
        assertThat(rejectReasonCode("0000000000000100")).isNull();
    }

    @Test
    void marketingFailureDoesNotFailPosting() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("5000.00")));
        when(accountClient.applyPosting(eq(ACCOUNT_ID), any())).thenReturn(account("5000.00"));
        doThrow(new RemoteServiceException("marketing down"))
                .when(marketingClient).evaluateRewards(any());

        PostingResult result = postingService.post(List.of(command("0000000000000103", "30.00")));

        assertThat(result.status()).isEqualTo("COMPLETED");
        assertThat(result.posted()).isEqualTo(1);
        assertThat(transactions.findByTransactionId("0000000000000103")).isPresent();
    }

    @Test
    void overlimitTransactionIsRejectedWithoutTouchingDownstreamPostings() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("2020.00")));

        PostingResult result = postingService.post(List.of(command("0000000000000101", "5000.00")));

        assertThat(result.status()).isEqualTo("COMPLETED_WITH_REJECTS");
        assertThat(result.posted()).isZero();
        assertThat(result.rejected()).isEqualTo(1);
        assertThat(result.rejections()).singleElement().satisfies(rejection -> {
            assertThat(rejection.transactionId()).isEqualTo("0000000000000101");
            assertThat(rejection.reasonCode()).isEqualTo(102);
            assertThat(rejection.reason()).isEqualTo("OVERLIMIT TRANSACTION");
        });

        verify(accountClient, never()).applyPosting(any(), any());
        assertThat(transactions.findByTransactionId("0000000000000101")).isEmpty();
        assertThat(dailyStatus("0000000000000101")).isEqualTo("REJECTED");
        assertThat(rejectReasonCode("0000000000000101")).isEqualTo(102);
        assertThat(jdbcTemplate.queryForObject(
                "select reject_reason from daily_transaction where transaction_id = ?", String.class,
                "0000000000000101")).isEqualTo("OVERLIMIT TRANSACTION");
        assertThat(balances.find(ACCOUNT_ID, "01", "0001")).get()
                .extracting(TranCategoryBalance::getBalance)
                .isEqualTo(new BigDecimal("1200.00"));
    }

    @Test
    void unknownCardIsRejectedWithoutCallingAccountService() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.empty());

        PostingResult result = postingService.post(List.of(command("0000000000000102", "10.00")));

        assertThat(result.rejected()).isEqualTo(1);
        assertThat(result.rejections()).singleElement()
                .extracting("reasonCode").isEqualTo(100);
        verify(accountClient, never()).findAccount(any());
        verify(accountClient, never()).applyPosting(any(), any());
    }

    @Test
    void duplicateTransactionIdIsIdempotent() {
        when(cardClient.findCard(CARD_NUMBER)).thenReturn(Optional.of(card));
        when(accountClient.findAccount(ACCOUNT_ID)).thenReturn(Optional.of(account("5000.00")));
        when(accountClient.applyPosting(eq(ACCOUNT_ID), any())).thenReturn(account("5000.00"));

        PostingResult first = postingService.post(List.of(command("0000000000000103", "75.00")));
        PostingResult second = postingService.post(List.of(command("0000000000000103", "75.00")));

        assertThat(first.posted()).isEqualTo(1);
        assertThat(first.duplicates()).isEmpty();
        assertThat(second.posted()).isEqualTo(1);
        assertThat(second.rejected()).isZero();
        assertThat(second.duplicates()).containsExactly("0000000000000103");
        assertThat(balances.find(ACCOUNT_ID, "01", "0001")).get()
                .extracting(TranCategoryBalance::getBalance)
                .isEqualTo(new BigDecimal("1275.00"));
        verify(accountClient).applyPosting(ACCOUNT_ID, new BigDecimal("75.00"));
    }

    private String dailyStatus(String transactionId) {
        return jdbcTemplate.queryForObject(
                "select status from daily_transaction where transaction_id = ?", String.class, transactionId);
    }

    private Integer rejectReasonCode(String transactionId) {
        return jdbcTemplate.queryForObject(
                "select reject_reason_code from daily_transaction where transaction_id = ?",
                Integer.class, transactionId);
    }
}

package com.carddemo.transaction.domain.service;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.assertj.core.api.Assertions.assertThat;

class InterestCalculatorTest {

    private final InterestCalculator calculator = new InterestCalculator();

    @Test
    void computesMonthlyInterestFromAnnualRate() {
        // BR-INT-01：1200.00 × 18.00 ÷ 1200 = 18.00
        assertThat(calculator.monthlyInterest(new BigDecimal("1200.00"), new BigDecimal("18.00")))
                .isEqualByComparingTo("18.00");
    }

    @Test
    void roundsHalfUpToTwoDecimals() {
        // 33.33 × 18.00 ÷ 1200 = 0.499950 → 0.50
        assertThat(calculator.monthlyInterest(new BigDecimal("33.33"), new BigDecimal("18.00")))
                .isEqualByComparingTo("0.50");
        // 100.05 × 18.00 ÷ 1200 = 1.500750 → 1.50
        assertThat(calculator.monthlyInterest(new BigDecimal("100.05"), new BigDecimal("18.00")))
                .isEqualByComparingTo("1.50");
        // 100.10 × 18.00 ÷ 1200 = 1.501500 → 1.50
        assertThat(calculator.monthlyInterest(new BigDecimal("100.10"), new BigDecimal("18.00")))
                .isEqualByComparingTo("1.50");
        // 100.15 × 18.00 ÷ 1200 = 1.502250 → 1.50
        assertThat(calculator.monthlyInterest(new BigDecimal("100.15"), new BigDecimal("18.00")))
                .isEqualByComparingTo("1.50");
        // 133.40 × 18.00 ÷ 1200 = 2.001000 → 2.00
        assertThat(calculator.monthlyInterest(new BigDecimal("133.40"), new BigDecimal("18.00")))
                .isEqualByComparingTo("2.00");
    }

    @Test
    void returnsZeroWhenRateIsZero() {
        assertThat(calculator.monthlyInterest(new BigDecimal("1500.00"), new BigDecimal("0.00")))
                .isEqualByComparingTo("0.00");
    }
}

package com.carddemo.transaction.domain.service;

import com.carddemo.transaction.domain.model.AccountSnapshot;
import com.carddemo.transaction.domain.model.CardSnapshot;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.assertj.core.api.Assertions.assertThat;

class PostingPolicyTest {

    private static final LocalDate ORIGINAL_DATE = LocalDate.of(2026, 9, 15);

    private final PostingPolicy policy = new PostingPolicy();

    private final CardSnapshot card = new CardSnapshot("0500024453765740", "00000000001", "000000001",
            "IMMANUEL KESSLER", LocalDate.of(2028, 5, 20), "Y");

    private AccountSnapshot account(String creditLimit, String cycleCredit, String cycleDebit,
                                    LocalDate expirationDate) {
        return new AccountSnapshot("00000000001", "Y", new BigDecimal("1940.00"),
                new BigDecimal(creditLimit), new BigDecimal("1020.00"), new BigDecimal(cycleCredit),
                new BigDecimal(cycleDebit), expirationDate, "A000000000");
    }

    @Test
    void rejectsWhenCardDoesNotExist() {
        assertThat(policy.evaluate(null, account("2020.00", "0.00", "0.00", LocalDate.of(2028, 5, 20)),
                new BigDecimal("10.00"), ORIGINAL_DATE))
                .hasValueSatisfying(reason -> {
                    assertThat(reason.getCode()).isEqualTo(100);
                    assertThat(reason.getDescription()).isEqualTo("INVALID CARD NUMBER FOUND");
                });
    }

    @Test
    void rejectsWhenAccountDoesNotExist() {
        assertThat(policy.evaluate(card, null, new BigDecimal("10.00"), ORIGINAL_DATE))
                .hasValueSatisfying(reason -> {
                    assertThat(reason.getCode()).isEqualTo(101);
                    assertThat(reason.getDescription()).isEqualTo("ACCOUNT RECORD NOT FOUND");
                });
    }

    @Test
    void rejectsWhenProjectedCycleExceedsCreditLimit() {
        assertThat(policy.evaluate(card, account("2020.00", "1900.00", "0.00", LocalDate.of(2028, 5, 20)),
                new BigDecimal("120.01"), ORIGINAL_DATE))
                .hasValueSatisfying(reason -> {
                    assertThat(reason.getCode()).isEqualTo(102);
                    assertThat(reason.getDescription()).isEqualTo("OVERLIMIT TRANSACTION");
                });
    }

    @Test
    void rejectsWhenAccountExpiredBeforeOriginalDate() {
        assertThat(policy.evaluate(card, account("5000.00", "0.00", "0.00", LocalDate.of(2026, 9, 14)),
                new BigDecimal("10.00"), ORIGINAL_DATE))
                .hasValueSatisfying(reason -> {
                    assertThat(reason.getCode()).isEqualTo(103);
                    assertThat(reason.getDescription())
                            .isEqualTo("TRANSACTION RECEIVED AFTER ACCT EXPIRATION");
                });
    }

    @Test
    void acceptsTransactionWithinLimitAndBeforeExpiration() {
        assertThat(policy.evaluate(card, account("2020.00", "1900.00", "0.00", LocalDate.of(2028, 5, 20)),
                new BigDecimal("120.00"), ORIGINAL_DATE))
                .isEmpty();
    }
}

package com.carddemo.transaction.interfaces.rest;

import com.carddemo.transaction.domain.model.AccountSnapshot;
import com.carddemo.transaction.domain.model.CardSnapshot;
