                    await load(0);
                } catch (error) {
                    msg.innerHTML = errBox(error);
                }
            });
        } catch (error) {
            box.innerHTML = errBox(error);
        }
    };

    form.addEventListener('submit', (event) => {
        event.preventDefault();
        load(0);
    });
    load(authUi.page);
}

